// NewLogsDecoder returns a LogsDecoder that detects the CloudTrail log format and
// processes records incrementally.
// Supported sub formats:
//   - S3 Records: streaming is supported; the offset is a record count and records
//     are skipped via WithOffset. Offset() reports the number of records processed.
//   - CloudWatch subscription filter and digest: the payload is decoded as a whole.
//     A non-zero offset is not supported and results in io.EOF on the first
//     DecodeLogs call, with Offset() reporting the total number of bytes consumed.
func (u *CloudTrailLogUnmarshaler) NewLogsDecoder(reader io.Reader, options ...encoding.DecoderOption) (encoding.LogsDecoder, error) {
	bufferedReader := bufio.NewReaderSize(reader, readerBufferSize)

	// Peek into the first 64 bytes to determine the type of CloudTrail log
	peekBytes, err := bufferedReader.Peek(64)
	if err != nil && !errors.Is(err, io.EOF) {
		return nil, fmt.Errorf("failed to peek into CloudTrail log: %w", err)
	}

	firstKey, err := extractFirstKey(peekBytes)
	if err != nil {
		return nil, fmt.Errorf("failed to extract the first JSON key: %w", err)
	}

	if firstKey == "Records" {
		return u.newS3RecordsDecoder(bufferedReader, options...)
	}

	// CloudWatch subscription filter and digest formats are decoded as a whole payload.
	return u.newWholePayloadDecoder(firstKey, bufferedReader, options...)
}

// newS3RecordsDecoder returns a LogsDecoder that streams individual records from a
// CloudTrail S3 Records file. The configured offset is treated as a record count and
// that many records are skipped before decoding begins.
func (u *CloudTrailLogUnmarshaler) newS3RecordsDecoder(reader *bufio.Reader, options ...encoding.DecoderOption) (encoding.LogsDecoder, error) {
	batchHelper := xstreamencoding.NewBatchHelper(options...)
	decoder := gojson.NewDecoder(reader)

	// Consume the opening '{', the "Records" key and the opening '[' of the array
	// so that decoder.More()/Decode operate on individual records.
	if token, err := decoder.Token(); err != nil || token != gojson.Delim('{') {
		return nil, fmt.Errorf("expected '{': %w", err)
	}
	if _, err := decoder.Token(); err != nil {
		return nil, fmt.Errorf("expected 'Records' key: %w", err)
	}
	if token, err := decoder.Token(); err != nil || token != gojson.Delim('[') {
		return nil, fmt.Errorf("expected '[': %w", err)
	}

	// For S3 Records the offset is a record count: skip that many records.
	offset := batchHelper.Options().Offset
	for skipped := int64(0); skipped < offset; skipped++ {
		if !decoder.More() {
			return nil, fmt.Errorf("EOF reached before offset %d records were discarded", offset)
		}
		var raw gojson.RawMessage
		if err := decoder.Decode(&raw); err != nil {
			return nil, err
		}
	}

	// current tracks the number of records processed so far, starting at the offset.
	current := offset

	return xstreamencoding.NewLogsDecoderAdapter(
		func() (plog.Logs, error) {
			logs, resourceLogs, scopeLogs := u.createLogs()
			logRecords := scopeLogs.LogRecords()

			init := true
			for decoder.More() {
				record := CloudTrailRecord{}
				if err := decoder.Decode(&record); err != nil {
					return plog.Logs{}, err
				}

				current++
				batchHelper.IncrementItems(1)

				if init {
					u.setResourceAttributes(resourceLogs.Resource().Attributes(), record)
					init = false
				}

				logRecord := logRecords.AppendEmpty()
				if err := u.setLogRecord(logRecord, &record); err != nil {
					return plog.Logs{}, err
				}

				if batchHelper.ShouldFlush() {
					batchHelper.Reset()
					return logs, nil
				}
			}

			if logRecords.Len() == 0 {
				return plog.NewLogs(), io.EOF
			}

			return logs, nil
		},
		func() int64 {
			return current
		},
	), nil
}

// newWholePayloadDecoder returns a LogsDecoder for the CloudWatch subscription filter
// and digest formats, which are decoded as a single payload. Streaming with an offset
// is not supported for these formats: when a non-zero offset is configured, the input
// is consumed and io.EOF is returned on the first DecodeLogs call, with the offset
// reporting the total number of bytes consumed.
func (u *CloudTrailLogUnmarshaler) newWholePayloadDecoder(firstKey string, reader *bufio.Reader, options ...encoding.DecoderOption) (encoding.LogsDecoder, error) {
	opts := encoding.NewDecoderOptions(options...)
	decoder := gojson.NewDecoder(reader)

	if opts.Offset > 0 {
		var raw gojson.RawMessage
		if err := decoder.Decode(&raw); err != nil {
			return nil, fmt.Errorf("failed to read CloudTrail payload: %w", err)
		}
		consumed := decoder.InputOffset()
		return xstreamencoding.NewLogsDecoderAdapter(
			func() (plog.Logs, error) {
				return plog.NewLogs(), io.EOF
			},
			func() int64 {
				return consumed
			},
		), nil
	}

	var logs plog.Logs
	var err error
	if isCloudWatchKey(firstKey) {
		logs, err = u.fromCloudWatch(decoder)
	} else {
		logs, err = u.fromDigest(decoder)
	}
	if err != nil {
		return nil, err
	}
	consumed := decoder.InputOffset()

	var done bool
	return xstreamencoding.NewLogsDecoderAdapter(
		func() (plog.Logs, error) {
			if done {
				return plog.NewLogs(), io.EOF
			}
			done = true
			return logs, nil
		},
		func() int64 {
			return consumed
		},
	), nil
}

