func TestValidateStream(t *testing.T) {
	directory := "testdata/stream"
	expectPattern := "cloudtrail_log_expect_%d.yaml"

	for _, uid := range []bool{false, true} {
		for _, tt := range []struct {
			name   string
			offset int64
			index  int
		}{
			{"Normal streaming", 0, 0},
			{"Stream with offset", 1, 1},
		} {
			t.Run(fmt.Sprintf("%s_uid=%v", tt.name, uid), func(t *testing.T) {
				data, err := os.ReadFile(filepath.Join(directory, "cloudtrail_log.json"))
				require.NoError(t, err)

				u := NewCloudTrailLogUnmarshaler(component.BuildInfo{}, uid)
				streamer, err := u.NewLogsDecoder(bytes.NewReader(data), encoding.WithFlushItems(1), encoding.WithOffset(tt.offset))
				require.NoError(t, err)

				index := tt.index
				for {
					index++
					var logs plog.Logs
					logs, err = streamer.DecodeLogs()
					if err != nil {
						if errors.Is(err, io.EOF) {
							break
						}
						t.Fatalf("failed to unmarshal log %d: %v", index, err)
					}
					require.Equal(t, int64(index), streamer.Offset())
					var expectedLogs plog.Logs
					expectedLogs, err = golden.ReadLogs(filepath.Join(directory, fmt.Sprintf(expectPattern, index)))
					require.NoError(t, err)
					require.NoError(t, plogtest.CompareLogs(expectedLogs, logs, plogtest.IgnoreResourceLogsOrder()))
				}
				_, err = streamer.DecodeLogs()
				require.ErrorIs(t, err, io.EOF)
				require.Equal(t, int64(3), streamer.Offset())
			})
		}
	}
}

